package com.holdoff.app.smsimport android.content.BroadcastReceiverimport android.content.ContentValuesimport android.content.Contextimport android.content.Intentimport android.net.Uriimport android.os.Buildimport android.provider.Telephonyimport android.telephony.SubscriptionManagerimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.launch/** * Default-SMS delivery endpoint. This receives SMS_DELIVER only after the user * explicitly grants HoldOff ROLE_SMS. It persists received SMS locally and * never analyzes, forwards, or replies to message content from this receiver. */class SmsDeliverReceiver : BroadcastReceiver() {    override fun onReceive(context: Context, intent: Intent) {        if (Telephony.Sms.Intents.SMS_DELIVER_ACTION != intent.action) return        val messages = Telephony.Sms.Intents.getMessagesFromIntent(intent)        if (messages.isEmpty()) return        val pendingResult = goAsync()        CoroutineScope(Dispatchers.IO).launch {            try {                // Android supplies the PDU parts in message order. Grouping retains                // that order while avoiding concatenation across different senders.                messages.groupBy { it.originatingAddress.orEmpty() }                    .filterKeys { it.isNotBlank() }                    .forEach { (address, parts) ->                        val body = parts.joinToString(separator = "") {                            it.displayMessageBody ?: it.messageBody.orEmpty()                        }                        if (body.isBlank()) return@forEach                        saveSmsToInbox(                            context = context,                            address = address,                            body = body,                            receivedAt = parts.first().timestampMillis,                            subscriptionId = subscriptionId(intent)                        )                    }            } finally {                pendingResult.finish()            }        }    }    private fun subscriptionId(intent: Intent): Int =        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP_MR1) {            intent.getIntExtra(                Telephony.Sms.Intents.EXTRA_SUBSCRIPTION_ID,                SubscriptionManager.INVALID_SUBSCRIPTION_ID            )        } else {            SubscriptionManager.INVALID_SUBSCRIPTION_ID        }    private fun saveSmsToInbox(        context: Context,        address: String,        body: String,        receivedAt: Long,        subscriptionId: Int    ): Uri? {        val values = ContentValues().apply {            put(Telephony.Sms.ADDRESS, address)            put(Telephony.Sms.BODY, body)            put(Telephony.Sms.DATE, receivedAt)            put(Telephony.Sms.DATE_SENT, receivedAt)            put(Telephony.Sms.READ, 0)            put(Telephony.Sms.SEEN, 0)            put(Telephony.Sms.TYPE, Telephony.Sms.MESSAGE_TYPE_INBOX)            if (subscriptionId != SubscriptionManager.INVALID_SUBSCRIPTION_ID) {                put(Telephony.Sms.SUBSCRIPTION_ID, subscriptionId)            }        }        return context.contentResolver.insert(Telephony.Sms.Inbox.CONTENT_URI, values)    }}
